'use strict';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let user=null,csrf='',courses=[],maps=[],accounts=[],audit=[],page='overview',query='',region='all',cursor=0,selectedCourse=new URLSearchParams(location.search).get('course')||'cn_bg_585',selectedHole='all',allMaps=[],working=false,feedbackItems=[],feedbackFilter='all';
const roleNames={admin:'管理员',editor:'内容编辑员',viewer:'只读人员'};
const regionNames=['北京市','天津市','河北省','山西省','内蒙古自治区','辽宁省','吉林省','黑龙江省','上海市','江苏省','浙江省','安徽省','福建省','江西省','山东省','河南省','湖北省','湖南省','广东省','广西壮族自治区','海南省','重庆市','四川省','贵州省','云南省','西藏自治区','陕西省','甘肃省','青海省','宁夏回族自治区','新疆维吾尔自治区','台湾省','香港特别行政区','澳门特别行政区'];
function notice(t){$('#notice').textContent=t;setTimeout(()=>$('#notice').textContent='',3500);}
async function api(path,method='GET',body){const res=await fetch('/api/'+path,{method,credentials:'same-origin',cache:'no-store',headers:body?{'Content-Type':'application/json','X-CSRF-Token':csrf}:{},body:body?JSON.stringify(body):undefined});let value;try{value=await res.json();}catch(e){throw Error('服务未连接，请使用项目管理服务打开此页面。');}if(!res.ok)throw Object.assign(Error(value.error||'操作未完成'),{status:res.status});return value;}
function button(a,t,cls='',extra=''){return `<button type="button" data-action="${a}" class="btn ${cls}" ${extra}>${t}</button>`;}
function tag(c){return c.operationStatus==='closed_reported'?'<span class="tag closed">来源标注关闭</span>':c.pars.length?'<span class="tag">可记分</span>':'<span class="tag warning">记分卡待补</span>';}
function currentCourse(){return courses.find(c=>c.id===selectedCourse)||courses[0];}
function holes(c){return c.segments.flatMap(s=>s.holes.map(h=>({...h,sectionName:s.name}))).map((h,i)=>({...h,number:i+1}));}
function formField(name,label,value='',extra=''){return `<label>${label}<input name="${name}" value="${esc(value)}" ${extra}></label>`;}
function option(v,t,selected){return `<option value="${esc(v)}" ${v===selected?'selected':''}>${esc(t)}</option>`;}
function dialog(title,body){$('#dialog-root').innerHTML=`<div class="dialog-shade"><section class="dialog" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="row"><h2>${esc(title)}</h2><button type="button" class="close" data-action="close" aria-label="关闭弹窗">×</button></div>${body}</section></div>`;$('#dialog-root input')?.focus();}
function closeDialog(){$('#dialog-root').innerHTML='';}
function authPage(setup=false,error=''){$('#manager').innerHTML=`<main class="auth-page"><section class="card auth-card"><div class="brand"><img src="/assets/logo.svg" alt="青野"><div>青野<small>QINGYE MANAGEMENT</small></div></div><div class="eyebrow">${setup?'WELCOME TO QINGYE':'MANAGEMENT CONSOLE'}</div><h1>${setup?'创建首位管理员':'登录管理后台'}</h1><p>${setup?'首次使用，请设置你的管理员账号。创建后即可管理球场、上传球道图及分配后台权限。':'管理每一座球场，照顾每一份资料。'}</p><form data-form="${setup?'setup':'login'}">${formField('username','登录名','','required minlength="3" maxlength="40" autocomplete="username" pattern="[A-Za-z0-9_.-]{3,40}" placeholder="字母、数字或_.-"')}${setup?formField('name','显示名称','','required maxlength="40" placeholder="例如：球场管理员"'):''}<label>密码<input name="password" type="password" required minlength="8" maxlength="128" autocomplete="${setup?'new-password':'current-password'}" placeholder="至少8个字符"></label>${setup?'<label>确认密码<input name="confirm" type="password" required minlength="8" autocomplete="new-password" placeholder="再次输入密码"></label>':''}<div class="error" id="auth-error">${esc(error)}</div><button class="btn primary" type="submit">${setup?'创建管理员并进入后台':'登录'}</button></form><a href="/">← 返回青野高尔夫</a><p class="hint" style="margin:20px 0 0">本机管理服务 · 球场和图片保存到本项目目录。</p></section></main>`;}
async function loadData(){const [cat,mi,logs]=await Promise.all([api('admin/catalog'),api('admin/maps'),user.role==='viewer'?Promise.resolve({items:[]}):api('admin/audit')]);courses=cat.courses;allMaps=mi.items;audit=logs.items;if(user.role==='admin'){const [a,f]=await Promise.all([api('admin/accounts'),api('admin/feedback')]);accounts=a.items;feedbackItems=f.items;}}
async function init(){try{const state=await api('auth/state');if(state.needsSetup)return authPage(true);try{const s=await api('auth/session');user=s.user;csrf=s.csrf;}catch(e){if(e.status===401)return authPage();throw e;}await loadData();render();}catch(e){$('#manager').innerHTML=`<div class="auth-page"><div class="card auth-card"><h2>管理服务暂未连接</h2><p>${esc(e.message)}</p>${button('retry','重新连接','primary')}</div></div>`;}}
function heading(title,sub,action=''){return `<div class="page-heading"><div><div class="eyebrow">QINGYE MANAGEMENT</div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`;}
function overview(){const mapped=new Set(allMaps.filter(i=>i.active).map(i=>i.courseId));return heading('把好球场，整理妥当。','球场资料、球道图和后台权限，在这里统一管理。',user.role!=='viewer'?button('upload','＋ 上传球道图','primary'):'')+`<div class="stats">${[['球场／分场资料',courses.length,'全国公开目录 + 后台补充'],['已发布球道图',allMaps.filter(i=>i.active&&i.kind==='hole').length,'按实际球洞 ID 对应'],['已有地图的球场',mapped.size,'总览与逐洞图'],['后台账户',user.role==='admin'?accounts.length:'—',user.role==='admin'?accounts.filter(a=>a.active).length+' 位已启用':'当前：'+roleNames[user.role]]].map(([t,n,s])=>`<div class="stat"><span>${t}</span><strong>${n}</strong><small>${s}</small></div>`).join('')}</div><div class="grid-two"><section class="card"><div class="section-title row"><div><h3>球场资料完整度</h3><p>资料有据可查，缺项留待补全。</p></div>${button('nav','查看球场','small','data-page="courses"')}</div><div class="list-line"><div class="grow"><b>可用逐洞记分卡</b><small>至少有一个完整九洞段</small></div><b>${courses.filter(c=>c.pars.length&&c.operationStatus!=='closed_reported').length} 条</b></div><div class="list-line"><div class="grow"><b>记分卡待补充</b><small>逐洞Par未取得或来源有异常</small></div><span class="tag warning">${courses.filter(c=>!c.pars.length).length} 条</span></div><div class="list-line"><div class="grow"><b>上海银涛球道图</b><small>18张逐洞图与2张来源总览图</small></div>${button('silver-maps','查看地图','small soft')}</div><div class="helper-box" style="margin:18px 0 0">在前台球场详情查看总览；记分页会按当前球洞打开对应球道图。其他球场已预留图片位置。</div></section>${user.role==='viewer'?'':`<section class="card"><div class="section-title"><h3>最近管理动态</h3><p>记录内容修改与账户管理操作。</p></div>${audit.slice(0,5).map(l=>`<div class="list-line"><div class="grow"><b>${esc(actionLabel(l.action))}</b><small>${esc(l.actorName)} · ${new Date(l.created*1000).toLocaleString('zh-CN')}</small></div></div>`).join('')||'<p class="hint">暂无管理动态。</p>'}</section>`}</div>`;}
function courseList(){const rows=courses.filter(c=>(region==='all'||c.province===region)&&(!query||[c.name,c.city,c.address,...c.aliases||[]].join(' ').toLowerCase().includes(query.toLowerCase())));cursor=Math.min(cursor,Math.max(0,Math.ceil(rows.length/20)-1));return heading('球场资料','维护名称、地区、地址与逐洞Par，原历史球局保留自己的快照。',user.role!=='viewer'?button('course-new','＋ 增加球场','primary'):'')+`<div class="filters"><input id="course-search" aria-label="搜索球场" placeholder="搜索球场、城市或地址" value="${esc(query)}"><select id="region" aria-label="地区筛选">${option('all','全部地区',region)+regionNames.map(r=>option(r,r,region)).join('')}</select></div><div id="course-results"><div class="table-wrap"><table><thead><tr><th>球场</th><th>地区</th><th>记分卡</th><th>地图</th><th>状态</th><th>管理</th></tr></thead><tbody>${rows.slice(cursor*20,cursor*20+20).map(c=>`<tr><td><b>${esc(c.name)}</b><small>${esc(c.id)}</small></td><td>${esc(c.province)}<small>${esc(c.city)}</small></td><td>${c.pars.length?c.holes+' 洞 · Par '+c.par:'待补充'}</td><td>${allMaps.filter(i=>i.active&&i.courseId===c.id).length} 张</td><td>${tag(c)}</td><td><div class="actions">${button('course-edit',user.role==='viewer'?'详情':'编辑','small',`data-id="${c.id}"`)}${button('course-maps','球道图','small soft',`data-id="${c.id}"`)}</div></td></tr>`).join('')||'<tr><td colspan="6" class="empty">暂无匹配球场</td></tr>'}</tbody></table></div><div class="pagination"><span>共 ${rows.length} 条 · 每页20条 · 第 ${cursor+1}/${Math.max(1,Math.ceil(rows.length/20))} 页</span><div class="actions">${button('paginate','上一页','small',`data-delta="-1" ${cursor===0?'disabled':''}`)}${button('paginate','下一页','small',`data-delta="1" ${(cursor+1)*20>=rows.length?'disabled':''}`)}</div></div></div>`;}
function mapPage(){const c=currentCourse();selectedCourse=c.id;const hs=holes(c),items=allMaps.filter(i=>i.courseId===c.id&&(selectedHole==='all'||selectedHole==='overview'&&i.kind==='overview'||i.holeId===selectedHole));return heading('球道图与地图','上传来源原图，绑定总览或具体球洞；发布后前台即可查看。',user.role!=='viewer'?button('upload','＋ 上传图片','primary'):'')+`<div class="filters"><input id="map-search" aria-label="查找地图球场" placeholder="搜索并切换球场" list="map-courses" value="${esc(c.name)}"><datalist id="map-courses">${courses.map(c=>`<option value="${esc(c.name)}">${esc(c.city)}</option>`).join('')}</datalist><select id="map-filter" aria-label="图片范围">${option('all','全部图片',selectedHole)+option('overview','球场总览',selectedHole)+hs.map(h=>option(h.id,'第'+h.number+'洞 · '+h.sectionName,selectedHole)).join('')}</select></div><section class="card map-summary"><div class="row"><div><h3>${esc(c.name)}</h3><p class="hint" style="margin-top:8px">${allMaps.filter(i=>i.active&&i.courseId===c.id&&i.kind==='hole').length} 张已发布逐洞图 · ${allMaps.filter(i=>i.active&&i.courseId===c.id&&i.kind==='overview').length} 张总览</p></div>${tag(c)}</div>${hs.length?`<div class="map-slots">${hs.map(h=>button('map-slot',h.number,`${allMaps.some(i=>i.active&&i.holeId===h.id)?'available':''} ${selectedHole===h.id?'selected':''}`,`data-id="${h.id}" aria-label="第${h.number}洞图片"`)).join('')}</div>`:'<p class="hint" style="margin-top:12px">先在球场资料里补全逐洞Par，再绑定具体球洞；总览可以先上传。</p>'}<p class="hint">浅色洞号为预留位置，绿色洞号已有图片。</p></section><div class="map-grid">${items.map(i=>`<article class="map-card"><a href="${esc('/'+i.url.replace(/^\//,''))}" target="_blank" rel="noopener"><img src="${esc('/'+i.url.replace(/^\//,''))}" alt="${esc(i.label)}" loading="lazy"></a><h3>${esc(i.label)}</h3><small>${i.kind==='overview'?'球场总览':esc(hs.find(h=>h.id===i.holeId)?'第'+hs.find(h=>h.id===i.holeId).number+'洞 · '+hs.find(h=>h.id===i.holeId).sectionName:i.holeId)}</small><div class="row"><span class="tag ${i.active?'':'gray'}">${i.active?'已发布':'已停用'}</span>${user.role!=='viewer'?button('map-toggle',i.active?'停用':'发布','small',`data-id="${i.id}" data-active="${!i.active}"`):''}</div></article>`).join('')||`<div class="map-empty-card"><div class="empty">尚未上传图片<br><small>总览与每个球洞的位置已预留</small></div></div>`}</div>`;}
function accountPage(){return heading('后台账户','按职责分配权限；停用或重置密码会立即撤销该账户的登录会话。',button('account-new','＋ 新建账户','primary'))+`<div class="table-wrap"><table><thead><tr><th>账户</th><th>权限</th><th>状态</th><th>操作</th></tr></thead><tbody>${accounts.map(a=>`<tr><td><b>${esc(a.name)}</b><small>${esc(a.username)}${a.id===user.id?' · 当前账户':''}</small></td><td>${roleNames[a.role]}</td><td><span class="tag ${a.active?'':'gray'}">${a.active?'已启用':'已停用'}</span></td><td>${button('account-edit','资料 / 权限 / 密码','small',`data-id="${a.id}"`)}</td></tr>`).join('')}</tbody></table></div><div class="helper-box" style="margin-top:20px">管理员可管理全部内容和后台账户；编辑员可维护球场、上传发布图片；只读人员仅可查看。这里管理后台工作人员账户，前台球友昵称与成绩仍保存在各自浏览器。</div>`;}
function actionLabel(v){return ({setup:'初始化管理员',login:'登录后台','course.create':'增加球场','course.update':'更新球场资料','map.upload':'上传球道图','map.publish':'发布图片','map.unpublish':'停用图片','account.create':'创建后台账户','account.update':'更新账户与权限'})[v]||v;}
function auditPage(){return heading('操作记录','最近200条管理操作，保留操作者、对象和时间。')+`<div class="table-wrap"><table><thead><tr><th>操作</th><th>对象 / 说明</th><th>操作者</th><th>时间</th></tr></thead><tbody>${audit.map(l=>`<tr><td>${esc(actionLabel(l.action))}</td><td>${esc(l.detail||l.target)}</td><td>${esc(l.actorName)}</td><td>${new Date(l.created*1000).toLocaleString('zh-CN')}</td></tr>`).join('')||'<tr><td class="empty">暂无记录</td></tr>'}</tbody></table></div>`;}
function dataPage(){return heading('数据与备份','后台内容与前台记分数据分别保存。')+`<section class="card backup-card"><h3>后台内容备份</h3><p>包含新增/修订球场、图片元数据、上传原图、用户反馈与联系方式、账户显示资料和最近操作记录。备份不包含密码、密码摘要或登录会话。恢复后台服务时保留本项目的data目录即可。</p>${user.role==='admin'?'<a class="btn primary" href="/api/admin/backup">下载后台内容备份</a>':'<span class="hint">请由管理员导出备份。</span>'}</section><section class="card backup-card"><h3>保存位置</h3><p>球场修订、后台账户和操作记录保存在项目的本地数据库；上传图片保存在本地图片目录。前台用户的历史球局仍通过“设置与数据管理”单独备份。</p><a href="/" target="_blank" rel="noopener">打开前台高尔夫软件 ↗</a></section>`;}
function render(){if(!user)return;const nav=[['overview','◫','概览'],['courses','⚑','球场资料'],['maps','▧','球道图管理'],...(user.role==='admin'?[['feedback','','用户反馈'+(feedbackItems.some(f=>f.status==='new')?' · '+feedbackItems.filter(f=>f.status==='new').length:'')],['accounts','♙','后台账户']]:[]),...(user.role!=='viewer'?[['audit','≡','操作记录'],['data','◇','数据与备份']]:[])];$('#manager').innerHTML=`<div class="layout"><aside class="sidebar"><a class="brand" href="/"><img src="/assets/logo.svg" alt="青野"><div>青野<small>MANAGEMENT CONSOLE</small></div></a><nav class="nav">${nav.map(([id,i,t])=>`<button data-action="nav" data-page="${id}" class="${page===id?'active':''}"><b>${i}</b>${t}</button>`).join('')}</nav><div class="sidebar-foot"><small>每一份资料，都有迹可循。</small><br><a href="/" target="_blank" rel="noopener">查看前台 ↗</a></div></aside><main class="main"><div class="topbar"><span class="crumb">工作台 / ${nav.find(n=>n[0]===page)?.[2]||'概览'}</span><div class="operator"><span class="avatar">${esc(user.name[0])}</span><span>${esc(user.name)} · ${roleNames[user.role]}</span>${button('logout','退出','small')}</div></div><div id="page-content">${({overview,courses:courseList,maps:mapPage,accounts:accountPage,feedback:feedbackPage,audit:auditPage,data:dataPage}[page]||overview)()}</div></main></div>`;}
const feedbackStates={new:'待查看',reading:'处理中',replied:'已回复',closed:'已处理'};
function feedbackPage(){const rows=feedbackItems.filter(f=>feedbackFilter==='all'||f.status===feedbackFilter);return heading('用户反馈','查看球友的问题与建议；保存回复后，用户可在“我的反馈”看到。')+`<div class="actions feedback-filters">${[['all','全部'],...Object.entries(feedbackStates)].map(([v,t])=>button('feedback-filter',t+(v==='all'?' · '+feedbackItems.length:' · '+feedbackItems.filter(f=>f.status===v).length),feedbackFilter===v?'primary small':'small',`data-value="${v}"`)).join('')}</div><div class="feedback-inbox">${rows.map(f=>`<article class="card"><div class="row"><span class="tag ${f.status==='new'?'warning':''}">${feedbackStates[f.status]}</span><small>${new Date(f.created*1000).toLocaleString('zh-CN')}</small></div><h3>${esc(f.category)}</h3><p class="feedback-message">${esc(f.content)}</p><small>${esc(f.id)} · 联系方式：${esc(f.contact||'未填写')}</small>${f.reply?`<div class="helper-box feedback-message"><b>已保存回复</b><p>${esc(f.reply)}</p></div>`:''}<div class="actions">${button('feedback-edit','查看 / 回复','small soft',`data-id="${f.id}"`)}</div></article>`).join('')||'<section class="card empty">暂无此状态的反馈</section>'}</div>`;}
function feedbackForm(id){const f=feedbackItems.find(f=>f.id===id);if(!f)return;dialog('处理用户反馈',`<div class="helper-box"><b>${esc(f.category)} · ${esc(f.id)}</b><p class="feedback-message">${esc(f.content)}</p><p>联系方式：${esc(f.contact||'未填写')}</p></div><form data-form="feedback" data-id="${f.id}"><label>处理状态<select name="status">${Object.entries(feedbackStates).map(([v,t])=>option(v,t,f.status)).join('')}</select></label><label>回复内容<textarea name="reply" maxlength="2000" rows="5" placeholder="回复会显示在用户的“我的反馈”里。">${esc(f.reply)}</textarea></label><div class="error"></div><div class="form-footer">${button('close','取消')}<button type="submit" class="btn primary">保存状态与回复</button></div></form>`);}
function courseForm(cid){const c=courses.find(c=>c.id===cid),ro=user.role==='viewer';dialog(c?'球场资料':'增加球场',`<form data-form="course" data-id="${c?.id||''}"><div class="form-grid"><div class="wide">${formField('name','球场名称',c?.name,'required maxlength="80"')}</div><label>所在地区<select name="province" required>${option('','请选择地区','')+regionNames.map(r=>option(r,r,c?.province)).join('')}</select></label>${formField('city','城市 / 区域',c?.city,'maxlength="40"')}${formField('longitude','经度',c?.longitude,'type="number" step="any" min="-180" max="180"')}${formField('latitude','纬度',c?.latitude,'type="number" step="any" min="-90" max="90"')}<label>坐标系<select name="coordinateSystem">${option('','待核实',c?.coordinateSystem||'')+option('gcj02','GCJ-02（微信 / 高德）',c?.coordinateSystem)+option('wgs84','WGS84（GPS）',c?.coordinateSystem)+option('bd09','BD-09（百度）',c?.coordinateSystem)}</select></label><label>坐标核实状态<select name="coordinateStatus">${option('source_point_unverified','来源点待核实',c?.coordinateStatus)+option('verified','已核实',c?.coordinateStatus)}</select></label><div class="wide">${formField('coordinateNote','坐标来源与核实说明',c?.coordinateNote,'maxlength="300"')}</div>
<div class="wide">${formField('address','球场地址',c?.address,'maxlength="250"')}</div>${formField('phone','联系电话',c?.phone,'maxlength="80"')}<label>营业状态<select name="operationStatus">${[['unknown','待核实'],['open_confirmed','已核对营业中'],['closed_reported','来源标注关闭']].map(([v,t])=>option(v,t,c?.operationStatus||'unknown')).join('')}</select></label><div class="wide">${formField('statusNote','核实说明 / 资料备注',c?.statusNote,'maxlength="300" placeholder="确认营业中时必填，例如核实日期与来源"')}</div><label class="wide">逐洞Par（${c?'修改时填写；留空保留当前记分卡':'选填，不填可先收录基础资料'}）<textarea name="pars" placeholder="例如：4,4,3,5,4,4,3,5,4（9洞）；18洞填写18个值">${c?.pars.length?esc(c.pars.join(',')):''}</textarea></label><label class="check wide"><input type="checkbox" name="confirmLayout">已核对逐洞Par；如改变洞数，确认重建可用洞段。历史球局保留原快照。</label></div><div class="error"></div><div class="form-footer">${button('close','关闭')}${!ro?'<button type="submit" class="btn primary">保存球场资料</button>':''}</div></form>`);if(ro)$('#dialog-root').querySelectorAll('input,select,textarea').forEach(e=>e.disabled=true);}
function uploadForm(){const c=currentCourse(),hs=holes(c);dialog('上传球场地图 / 球道图',`<form data-form="upload"><div class="helper-box">${esc(c.name)} · 图片按球场与球洞ID保存。支持JPG、PNG、WebP，单张8MB以内。</div><input type="hidden" name="courseId" value="${esc(c.id)}"><div class="form-grid"><label>图片类型<select name="kind" id="upload-kind"><option value="overview" ${selectedHole==='overview'?'selected':''}>球场总览</option><option value="hole" ${hs.length&&selectedHole!=='overview'?'selected':''} ${!hs.length?'disabled':''}>逐洞球道图</option></select></label><label>对应球洞<select name="holeId" id="upload-hole">${hs.map(h=>option(h.id,'第'+h.number+'洞 · '+h.sectionName+' '+h.label,selectedHole)).join('')}</select></label><div class="wide">${formField('label','图片标题','','required maxlength="80" placeholder="例如：第1洞球道图 / 球场总览"')}</div><label class="wide">选择图片<input id="image-file" name="image" type="file" accept="image/jpeg,image/png,image/webp" required><img id="upload-preview" class="upload-preview" alt="待上传图片预览" hidden></label>${formField('effectiveOn','图片版本日期（选填）','','type="date"')}${formField('sourceUrl','来源链接（选填）','','type="url" placeholder="https://..."')}<label class="wide">说明（选填）<textarea name="note" maxlength="500" placeholder="例如：球会提供的现行球道图"></textarea></label><label class="check wide"><input name="verified" type="checkbox">已向球会核对当前版本及球洞对应关系</label></div><div class="error"></div><div class="form-footer">${button('close','取消')}<button class="btn primary" type="submit">上传并发布</button></div></form>`);updateUploadKind();}
function updateUploadKind(){const e=$('#upload-hole');if(e)e.disabled=$('#upload-kind').value!=='hole';}
function accountForm(uid){const a=accounts.find(a=>a.id===uid);dialog(a?'管理后台账户':'新建后台账户',`<form data-form="account" data-id="${a?.id||''}"><div class="form-grid">${formField('username','登录名',a?.username,`${a?'disabled':'required pattern="[A-Za-z0-9_.-]{3,40}"'} autocomplete="off" maxlength="40"`)}${formField('name','显示名称',a?.name,'required maxlength="40"')}<label>权限<select name="role">${Object.entries(roleNames).map(([v,t])=>option(v,t,a?.role||'editor')).join('')}</select></label><label>状态<select name="active">${option('1','启用',a&&!a.active?'0':'1')+option('0','停用',a&&!a.active?'0':'1')}</select></label><label class="wide">${a?'重置密码（留空保持原密码）':'初始密码'}<input type="password" name="password" minlength="8" maxlength="128" ${a?'':'required'} autocomplete="new-password" placeholder="至少8个字符"></label></div><p class="hint">始终保留至少一位启用的管理员。修改权限、停用或重置密码后，该账户需重新登录。</p><div class="error"></div><div class="form-footer">${button('close','取消')}<button type="submit" class="btn primary">保存账户</button></div></form>`);}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;try{
 if(a==='feedback-filter'){feedbackFilter=b.dataset.value;return render();}if(a==='feedback-edit')return feedbackForm(b.dataset.id);
 if(a==='close')return closeDialog();if(a==='retry')return init();
 if(a==='nav'){page=b.dataset.page;if(['accounts','feedback'].includes(page)&&user.role!=='admin')return;cursor=0;query='';render();return;}
 if(a==='logout'){await api('auth/logout','POST',{});user=null;return authPage();}
 if(a==='paginate'){cursor+=Number(b.dataset.delta);return render();}
 if(a==='course-new')return courseForm();if(a==='course-edit')return courseForm(b.dataset.id);
 if(a==='course-maps'||a==='silver-maps'){selectedCourse=a==='silver-maps'?'cn_bg_585':b.dataset.id;selectedHole='all';page='maps';return render();}
 if(a==='upload')return uploadForm();if(a==='map-slot'){selectedHole=b.dataset.id;return render();}
 if(a==='map-toggle'){await api('admin/maps/'+b.dataset.id,'PUT',{active:b.dataset.active==='true'});await loadData();render();notice('图片发布状态已更新');return;}
 if(a==='account-new')return accountForm();if(a==='account-edit')return accountForm(b.dataset.id);
 }catch(error){notice(error.message);}});
document.addEventListener('input',e=>{if(e.target.id==='course-search'){query=e.target.value;cursor=0;const start=e.target.selectionStart;$('#page-content').innerHTML=courseList();$('#course-search').focus();$('#course-search').setSelectionRange(start,start);}});
document.addEventListener('change',e=>{const t=e.target;if(t.id==='region'){region=t.value;cursor=0;render();}if(t.id==='map-search'){const c=courses.find(c=>c.name===t.value);if(c){selectedCourse=c.id;selectedHole='all';render();}else notice('请从球场候选中选择');}if(t.id==='map-filter'){selectedHole=t.value;render();}if(t.id==='upload-kind')updateUploadKind();if(t.id==='image-file'){const file=t.files[0];if(!file)return;if(file.size>8*1024*1024){t.value='';notice('单张图片须在8MB以内');return;}const img=$('#upload-preview');img.src=URL.createObjectURL(file);img.hidden=false;img.onload=()=>URL.revokeObjectURL(img.src);}});
document.addEventListener('submit',async e=>{const f=e.target,type=f.dataset.form;if(!type)return;e.preventDefault();if(working)return;working=true;const fd=new FormData(f),value=Object.fromEntries(fd),error=f.querySelector('.error'),submit=f.querySelector('[type=submit]');if(error)error.textContent='';if(submit)submit.disabled=true;
 try{
 if(type==='setup'||type==='login'){
  if(type==='setup'){if(value.password!==value.confirm)throw Error('两次密码输入不一致');await api('auth/setup','POST',{username:value.username,name:value.name,password:value.password});}
  const session=await api('auth/login','POST',{username:value.username,password:value.password});user=session.user;csrf=session.csrf;await loadData();render();return;
 }
 if(type==='feedback'){if(value.reply.trim()&&value.status==='new')value.status='replied';await api('admin/feedback/'+f.dataset.id,'PUT',value);closeDialog();await loadData();render();notice('反馈状态与回复已保存');}
 if(type==='course'){const body={...value};if(value.pars.trim()){const pars=value.pars.trim().split(/[,，\s]+/).map(Number);if(![9,18,27,36].includes(pars.length)||pars.some(p=>![3,4,5,6].includes(p)))throw Error('请填写9/18/27/36个有效Par（3–6）');const old=courses.find(c=>c.id===f.dataset.id);if(!old||JSON.stringify(old.pars)!==JSON.stringify(pars)){if(!fd.has('confirmLayout'))throw Error('请先核对并勾选逐洞Par确认');body.pars=pars;body.confirmLayout=true;}else delete body.pars;}else delete body.pars;await api('admin/courses'+(f.dataset.id?'/'+f.dataset.id:''),f.dataset.id?'PUT':'POST',body);closeDialog();await loadData();render();notice('球场资料已保存，前台刷新后可见');}
 if(type==='upload'){const file=fd.get('image');if(!file?.size)throw Error('请选择图片');if(file.size>8*1024*1024)throw Error('单张图片须在8MB以内');try{const bitmap=await createImageBitmap(file);if(bitmap.width>12000||bitmap.height>12000||bitmap.width*bitmap.height>40000000){bitmap.close();throw Error('图片尺寸过大，请压缩后重试');}bitmap.close();}catch(error){throw Error(error.message.includes('尺寸')?error.message:'图片无法解码，请选择完整的JPG、PNG或WebP图像');}const image=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);});await api('admin/maps','POST',{...value,image,verified:fd.has('verified')});closeDialog();await loadData();render();notice('图片已发布，前台对应位置现在可以查看');}
 if(type==='account'){await api('admin/accounts'+(f.dataset.id?'/'+f.dataset.id:''),f.dataset.id?'PUT':'POST',{...value,active:value.active==='1'});closeDialog();if(f.dataset.id===user.id){user=null;authPage(false,'当前账户资料已更新，请重新登录。');}else{await loadData();render();notice('后台账户已保存');}}
 }catch(e){if(error)error.textContent=e.message;else notice(e.message);}finally{working=false;if(submit)submit.disabled=false;}
});
init();

setInterval(async()=>{if(user?.role!=='admin'||document.hidden)return;try{const value=await api('admin/feedback');if(JSON.stringify(value.items)!==JSON.stringify(feedbackItems)){feedbackItems=value.items;render();}}catch(e){}},30000);
